// Static sap emission, matched to the current native type-6 root tile recipe.
export const ROOT_EMISSION_SPEC=Object.freeze({maxCells:4096,maxSources:6,maxCacheSide:1024});
const hash=n=>{n=Math.imul(n^n>>>16,0x45d9f3b);return ((n^(n>>>16))>>>0)/4294967296;};
export function createRootEmission(room,{makeCanvas}){
 const sprites=new Map();let cells=[],sources=[],ref=null,signature=0,revision=0,cacheKey='',surface=null,reveal=null,bounds=null,dead=false;
 function sprite(variant){if(sprites.has(variant))return sprites.get(variant);const image=makeCanvas(104,80),c=image.getContext('2d');c.setTransform(4,0,0,4,52,40);if(variant&1)c.scale(-1,1);c.lineJoin='round';c.lineCap='round';c.strokeStyle='#8eff4b';c.globalAlpha=.55;c.lineWidth=.95;c.beginPath();c.moveTo(-12,4);c.lineTo(-6,.2);c.lineTo(-1,-.8);c.lineTo(4,-4.8);c.lineTo(12,-5.8);c.stroke();c.globalAlpha=.88;c.strokeStyle='#c5ff84';c.lineWidth=.4;c.beginPath();if(variant&2){c.moveTo(-11,3.4);c.lineTo(-6,.2);c.lineTo(-2,-.65);}else{c.moveTo(1,-2.4);c.lineTo(4,-4.8);c.lineTo(10,-5.55);}c.stroke();sprites.set(variant,image);return image;}
 function update(masks){if(dead)return;const cols=room.cols||21;let next=0;for(const p of masks.cells)next=Math.imul(next^((p.y*cols+p.x)*7+(room.terrain?.[p.y*cols+p.x]||0)),16777619);if(ref===masks&&signature===next)return;ref=masks;signature=next;revision++;cells=masks.cells.filter(p=>room.terrain?.[p.y*cols+p.x]===6).slice(0,ROOT_EMISSION_SPEC.maxCells).map(p=>{const index=p.y*cols+p.x;return {...p,px:50+22*p.x+2*p.y,py:57.5+16*p.y,variant:Math.floor(hash(room.seed+index*157)*4),priority:hash(room.seed+index*691)};});sources=[];for(const p of [...cells].sort((a,b)=>a.priority-b.priority))if(sources.length<ROOT_EMISSION_SPEC.maxSources&&sources.every(q=>Math.abs(q.x-p.x)+Math.abs(q.y-p.y)>=3))sources.push(p);bounds=cells.length?{x:Math.floor(Math.min(...cells.map(p=>p.px)))-40,y:Math.floor(Math.min(...cells.map(p=>p.py)))-30,w:Math.ceil(Math.max(...cells.map(p=>p.px))-Math.min(...cells.map(p=>p.px)))+80,h:Math.ceil(Math.max(...cells.map(p=>p.py))-Math.min(...cells.map(p=>p.py)))+60}:null;}
 function prepare(masks,gain){if(!bounds)return false;const key=revision+':'+Math.round(gain*100);if(cacheKey===key)return true;const b=bounds,scale=Math.min(1,1024/b.w,1024/b.h),w=Math.ceil(b.w*scale),h=Math.ceil(b.h*scale);surface??=makeCanvas(1,1);reveal??=makeCanvas(1,1);for(const image of[surface,reveal]){image.width=w;image.height=h;image.getContext('2d').setTransform(scale,0,0,scale,-b.x*scale,-b.y*scale);}const c=surface.getContext('2d'),m=reveal.getContext('2d');c.save();c.clip(masks.floor);m.save();m.clip(masks.floor);for(const p of cells){const im=sprite(p.variant);c.globalAlpha=Math.min(1,gain*.68);c.drawImage(im,p.px-13,p.py-10,26,20);m.globalAlpha=Math.min(1,gain*.94);m.drawImage(im,p.px-13,p.py-10,26,20);}for(const p of sources){const r=24,g=c.createRadialGradient(p.px,p.py,0,p.px,p.py,r),a=m.createRadialGradient(p.px,p.py,0,p.px,p.py,r);g.addColorStop(0,'#8cff4555');g.addColorStop(1,'#8cff4500');a.addColorStop(0,'#00000060');a.addColorStop(1,'#00000000');for(const [ctx,fill]of[[c,g],[m,a]]){ctx.save();ctx.clip(masks.sourcePath(p));ctx.globalAlpha=Math.min(1,gain);ctx.fillStyle=fill;ctx.fillRect(p.px-r,p.py-r,r*2,r*2);ctx.restore();}}c.restore();m.restore();cacheKey=key;return true;}
 return {update,paintGround(c,masks,{gain=1,duck=1}={}){if(dead||gain<=0||!prepare(masks,gain))return;c.save();c.globalCompositeOperation='screen';c.globalAlpha*=duck;c.drawImage(surface,bounds.x,bounds.y,bounds.w,bounds.h);c.restore();},paintNight(c,v,masks,{gain=1}={}){if(dead||gain<=0||!prepare(masks,gain))return;c.save();c.globalAlpha=1;c.drawImage(reveal,bounds.x-v.x+4,bounds.y-v.y+4,bounds.w,bounds.h);c.restore();},status:()=>({cells:cells.length,sources:sources.length,sprites:sprites.size,revision,canvasBytes:[surface,reveal,...sprites.values()].filter(Boolean).reduce((n,c)=>n+c.width*c.height*4,0)}),dispose(){dead=true;for(const c of[surface,reveal,...sprites.values()].filter(Boolean))c.width=c.height=1;sprites.clear();surface=reveal=null;cells=[];sources=[];ref=null;}};
}
